  "Old history is cleaned up automatically, but this database still holds the freed space. Run the command on":
    "旧历史会自动清理，但数据库仍占用已释放的空间。请在",
  "to return it to disk; it pauses and restarts the background service. Quit the desktop app first if it hosts this environment.":
    "上运行此命令，将空间归还给磁盘。此操作会暂停并重启后台服务。如果此环境由桌面应用托管，请先退出桌面应用。",
  from: "从",
  "EAS Simulator": "EAS 模拟器",
  "Run iOS Simulators in Expo's cloud from this environment. Sessions bill the Expo account until they stop, so each host limits how many run and for how long. Editing or removing a host stops its running sessions.":
    "通过此环境在 Expo 云端运行 iOS 模拟器。会话停止前会持续向 Expo 账户计费，因此每个主机都设有并发会话数和运行时长限制。编辑或移除主机会停止其正在运行的会话。",
  "Add EAS host": "添加 EAS 主机",
  "No EAS hosts.": "暂无 EAS 主机。",
  "The environment's server signs in to Expo and starts the sessions. Without a token here it uses EXPO_TOKEN, then its eas login.":
    "此环境的服务器负责登录 Expo 并启动会话。如果未在此设置令牌，将依次尝试使用 EXPO_TOKEN 和服务器上的 eas login 登录状态。",
  "Expo access token": "Expo 访问令牌",
  "Clear access token": "清除访问令牌",
  "Check account": "检查账户",
  "EAS project": "EAS 项目",
  "From the thread's project": "使用任务所属项目",
  "Sessions bill the project's Expo account. \"From the thread's project\" reads extra.eas.projectId from the project's app config.":
    "会话费用计入项目的 Expo 账户。“使用任务所属项目”会读取该项目应用配置中的 extra.eas.projectId。",
  "Expo allows sessions of up to 40 minutes on free accounts and 115 on paid ones, and ends one after the idle minutes without activity, so idle minutes must be smaller than session minutes.":
    "Expo 免费账户的会话最长可运行 40 分钟，付费账户最长 115 分钟。连续无操作达到空闲时限后，会话将结束，因此空闲时限必须短于会话时限。",
  "Save host": "保存主机",
  "What the address bar searches when you type something that isn't a URL.":
    "在地址栏输入非网址内容时使用的搜索引擎。",
  "search engine": "搜索引擎",
  "Search engine": "搜索引擎",
  "Custom search URL": "自定义搜索网址",
  "Use %s where the search terms go.": "用 %s 表示搜索词的位置。",
  "default browser access": "默认浏览器访问权限",
  "Connect to your server from your phone or tablet.": "通过手机或平板电脑连接到服务器。",
  "Scan with your phone camera.": "使用手机相机扫描。",
  "Run only when every filter matches. Other requests are logged as filtered. Separate “is one of” values with commas; a value can't contain a comma.":
    "仅在所有筛选条件均匹配时运行。其他请求会被记录为已过滤。“属于以下任一值”的多个值用逗号分隔，单个值不能包含逗号。",
  "Add filter": "添加筛选条件",
  "Next run": "下次运行",
  "Replay key": "重放去重键",
  "Coalesce key": "合并键",
  "Coalesce window": "合并时间窗口",
  "Replay keys suppress repeat deliveries for 7 days. Coalescing runs the latest payload once when the window from the first delivery closes. Empty keys run normally.":
    "重放去重键会在 7 天内拦截重复投递。合并时间窗口从首次投递开始计时，窗口结束后仅使用最新请求内容运行一次。键为空时照常运行。",
  "Same on all machines": "所有设备一致",
  "Typeset LaTeX math, such as $x^2$ or \\[x^2\\], in messages and Markdown previews. The composer keeps TeX source editable.":
    "在消息和 Markdown 预览中排版 LaTeX 公式，例如 $x^2$ 或 \\[x^2\\]。输入框中仍可编辑 TeX 源码。",
