  "Use stable releases or nightly builds. Switch back anytime.":
    "使用稳定版或每日构建版，可随时切换。",
  Motion: "动效",
  "Set how fast panels open and close.": "设置面板打开和关闭的速度。",
  "Higher values make menus, dialogs, and the composer more solid.":
    "数值越高，菜单、对话框和输入区越不透明。",
  "Use thinner grayscale text smoothing instead of the macOS default.":
    "使用更轻薄的灰阶文字平滑效果，替代 macOS 默认效果。",
  "Restore Build/Plan, /plan, /default, and Shift+Tab. Off uses build mode.":
    "恢复构建/规划、/plan、/default 和 Shift+Tab。关闭后使用构建模式。",
  "Shows context window usage as a circular indicator in the composer.":
    "在输入区中以圆形指示器显示上下文窗口用量。",
  "Stream output token by token. This legacy mode is slower and harder to follow.":
    "逐个 Token 流式输出。此旧版模式速度较慢，也较难阅读。",
  "Restore per-project thread trees instead of the default flat sidebar.":
    "恢复按项目分组的任务树，替代默认的扁平侧栏。",
  "Show diffs stacked or side by side. The toggle in the diff toolbar changes this too.":
    "选择上下或并排显示差异；差异工具栏中的开关也会更改此设置。",
  "Open linked pull requests when found and turn diffs when work finishes.":
    "发现关联拉取请求时自动打开，并在工作完成后切换到差异面板。",
  "Rest the composer of an existing thread into a single line when it loses focus, when you scroll the conversation, or both. Pick neither to keep it expanded.":
    "现有任务的输入区失去焦点、滚动对话或同时满足两者时收起为单行；均不选择则保持展开。",
  "Automatically resume active threads after a server update restarts the environment.":
    "服务端更新并重启环境后，自动恢复进行中的任务。",
  "Choose whether the desktop app quits immediately, after a hold, or after two quick presses.":
    "选择桌面客户端立即退出、长按后退出，或快速按两次后退出。",
  "Hold mode also quits on two quick presses.": "长按模式下，快速按两次也会退出客户端。",
  "Used for thread titles and other generated text. Source control can override it.":
    "用于任务标题和其他生成文本；源代码管理可以单独覆盖此设置。",
  "Tab size for you and agents. Fill fits the panel; other sizes show the device toolbar.":
    "设置你和 Agent 使用的标签页尺寸。填满面板会自适应，其余尺寸会显示设备工具栏。",
  "Maximum recording rate. 30 fps saves CPU and storage; 60 fps is smoother.":
    "最大录制帧率。30 fps 更节省处理器和存储空间，60 fps 更流畅。",
  "Where links in the chat and terminal open. Hold ⌘ or Ctrl while clicking a chat link to open it in your default browser either way.":
    "选择对话和终端中的链接打开位置。按住 ⌘ 或 Ctrl 点击对话链接时，始终使用默认浏览器打开。",
  "Allow agents to use the preview browser. Off hides browser tools from agents, not you.":
    "允许 Agent 使用预览浏览器。关闭后仅对 Agent 隐藏浏览器工具，不影响你使用。",
  "Show the floating preview when an agent opens a browser unless the agent says otherwise.":
    "Agent 打开浏览器时显示浮动预览，除非 Agent 明确要求其他方式。",
  "You're not connected to a server yet.": "尚未连接到服务端。",
  "Profiles separate cookies and logins. Incognito data is cleared when the app closes.":
    "配置文件会隔离 Cookie 和登录状态；客户端关闭后会清除无痕数据。",
  "Refresh provider status, versions, and models in the background. Set to 0 to disable.":
    "在后台刷新服务提供方状态、版本和模型；设为 0 可禁用。",
  "Use Conventional Commit prefixes and keep change request text concise.":
    "使用 Conventional Commit 前缀，并保持变更请求文案简洁。",
  "Use your instructions for change descriptions and change requests in every project.":
    "在所有项目中使用你的变更说明和变更请求写作指令。",
  "Use the repository's template for change request descriptions when available.":
    "仓库提供模板时，使用该模板编写变更请求说明。",
  "Model for source control text and branch or bookmark names. Off uses the global default.":
    "用于源代码管理文案以及分支或书签名称的模型。关闭时使用全局默认模型。",
  "Connect a CLIProxyAPI hub to show its accounts on Usage → Limits.":
    "连接 CLIProxyAPI Hub，在“用量 → 限额”中显示其账号。",
  "Not installed on this machine.": "此设备上未安装。",
  "Needs Keychain access to read its cookies.": "需要访问系统钥匙串才能读取 Cookie。",
  "No encryption key in your Keychain: sign in to that browser once, then retry.":
    "系统钥匙串中没有加密密钥。请先在该浏览器中登录一次，然后重试。",
  "Quit the browser first so its cookie database can be read.":
    "请先退出浏览器，以便读取其 Cookie 数据库。",
  "Importing from this browser isn't possible on this platform.": "当前平台无法从此浏览器导入。",
  "The system keyring could not be accessed. Make sure your desktop keyring is running and unlocked, then retry.":
    "无法访问系统密钥环。请确认桌面密钥环正在运行且已解锁，然后重试。",
  "That browser is no longer available to import from.": "该浏览器已无法作为导入来源。",
